export function normalizeName(name: string): string {
  return name.trim().toUpperCase().replace(/\s+/g, " ");
}

/** Sheet acuan gabungan untuk sebuah kelompok kelas/jurusan, atau null bila tidak tercakup. */
export function kelasSheetForGroup(group: string): string | null {
  const g = group.trim().toUpperCase();
  if (g === "KLS 10 DKV") return "KELAS 10";
  return null;
}

export function kelasResult(sheet: string, nama: string): KelasResultEntry | null {
  return EXCEL_KELAS_RESULTS[sheet]?.[normalizeName(nama)] ?? null;
}
